<!-- Inline Script for Filtering, Search, Modal, and Estimator -->
<script>
    function filterCategory(category) {
      const items = document.querySelectorAll('.product-item');
      let visibleCount = 0;
      
      items.forEach(item => {
        const itemCat = item.getAttribute('data-cat');
        if (category === 'all' || itemCat === category) {
          item.classList.remove('hidden');
          visibleCount++;
        } else {
          item.classList.add('hidden');
        }
      });

      // Update filter tab active classes
      const tabs = document.querySelectorAll('.filter-tab');
      tabs.forEach(tab => {
        if (tab.getAttribute('data-cat') === category) {
          tab.className = 'filter-tab px-3.5 py-1.5 rounded-full font-label-caps text-label-caps uppercase tracking-wider bg-primary text-on-primary whitespace-nowrap transition-colors';
        } else {
          tab.className = 'filter-tab px-3.5 py-1.5 rounded-full font-label-caps text-label-caps uppercase tracking-wider bg-surface-container-highest text-on-surface-variant hover:bg-secondary-container/60 whitespace-nowrap transition-colors';
        }
      });

      document.getElementById('activeCount').innerText = visibleCount;
    }

    function handleSearch(query) {
      const lower = query.toLowerCase().trim();
      const items = document.querySelectorAll('.product-item');
      let count = 0;

      items.forEach(item => {
        const text = item.innerText.toLowerCase();
        if (text.includes(lower)) {
          item.classList.remove('hidden');
          count++;
        } else {
          item.classList.add('hidden');
        }
      });
      document.getElementById('activeCount').innerText = count;
    }

    function openRfqModal(productName) {
      document.getElementById('modalProductInput').value = productName;
      document.getElementById('rfqModalBackdrop').classList.remove('hidden');
    }

    function closeRfqModal() {
      document.getElementById('rfqModalBackdrop').classList.add('hidden');
    }

    function handleModalSubmit(e) {
      e.preventDefault();
      closeRfqModal();
      showToast("RFQ transmitted to DSAM Engineering Estimators (24H SLA).");
    }

    function showToast(msg) {
      const toast = document.getElementById('toastNotification');
      document.getElementById('toastMessage').innerText = msg;
      toast.classList.remove('translate-y-24', 'opacity-0');
      toast.classList.add('translate-y-0', 'opacity-100');
      setTimeout(() => {
        toast.classList.remove('translate-y-0', 'opacity-100');
        toast.classList.add('translate-y-24', 'opacity-0');
      }, 4000);
    }

    function viewSpecDetail(title, desc) {
      showToast(`${title}: ${desc}`);
    }

    function calculateEstimate() {
      const volume = document.getElementById('estimatorVolume').value;
      const print = document.getElementById('estimatorPrint').value;
      const summary = document.getElementById('calculatedTierSummary');
      const lead = document.getElementById('estimatedLeadTime');

      if (volume >= 500000) {
        summary.innerText = "Tier 1 Enterprise Continuous Extrusion";
        lead.innerText = "10 to 14 Business Days (Full Fleet Run)";
      } else if (volume >= 100000) {
        summary.innerText = "Tier 2 Commercial High-Capacity Run";
        lead.innerText = "7 to 10 Business Days";
      } else {
        summary.innerText = "Standard Flexible Batch Line";
        lead.innerText = "3 to 5 Business Days";
      }

      if (print !== 'plain') {
        lead.innerText += " (+ Cylinder Plate Proofing)";
      }
    }

    function triggerEstimatorQuote() {
      const prod = document.getElementById('estimatorProduct').value;
      openRfqModal(prod + " (Calculated via Spec Builder)");
    }

    function downloadCatalogAlert() {
      showToast("Downloading DSAM 2026 Official Packaging Catalog (PDF)...");
    }
  </script>
